import{_ as e,o as t,c as r,al as i}from"./chunks/framework.BawR2jEz.js";const _=JSON.parse('{"title":"Сброс кэша и модификаторов","description":"Обновление OCMOD-модификаторов и очистка системного кэша OpenCart через верхнее меню exDoc.","frontmatter":{"title":"Сброс кэша и модификаторов","description":"Обновление OCMOD-модификаторов и очистка системного кэша OpenCart через верхнее меню exDoc."},"headers":[],"relativePath":"cache/index.md","filePath":"cache/index.md"}'),l={name:"cache/index.md"};function o(n,a,c,s,h,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="сброс-кэша-и-модификаторов" tabindex="-1">Сброс кэша и модификаторов <a class="header-anchor" href="#сброс-кэша-и-модификаторов" aria-label="Permalink to &quot;Сброс кэша и модификаторов&quot;">​</a></h1><p>Кнопка обновления в верхнем меню выполняет две операции: обновление OCMOD-модификаторов OpenCart и очистку системного кэша.</p><h2 id="что-происходит-при-нажатии" tabindex="-1">Что происходит при нажатии <a class="header-anchor" href="#что-происходит-при-нажатии" aria-label="Permalink to &quot;Что происходит при нажатии&quot;">​</a></h2><ol><li><strong>Обновление модификаторов (OCMOD)</strong> — пересобираются скомпилированные файлы модификаторов OpenCart. Это необходимо после установки, обновления или удаления модулей.</li><li><strong>Очистка системного кэша</strong> — удаляется файловый кэш OpenCart (шаблоны, языковые файлы, данные модулей).</li></ol><p>После каждой операции появляется уведомление об успешном выполнении.</p><h2 id="когда-использовать" tabindex="-1">Когда использовать <a class="header-anchor" href="#когда-использовать" aria-label="Permalink to &quot;Когда использовать&quot;">​</a></h2><ul><li>После установки или обновления exDoc</li><li>После изменения OCMOD-файлов</li><li>Если изменения в модулях не отображаются на сайте</li><li>После обновления OpenCart или других модулей</li><li>При возникновении ошибок, связанных с кэшированием</li></ul><h2 id="важно" tabindex="-1">Важно <a class="header-anchor" href="#важно" aria-label="Permalink to &quot;Важно&quot;">​</a></h2><p>Эта функция очищает <strong>системный кэш OpenCart</strong>, а не кэш блоков exDoc. Кэш блоков очищается автоматически при сохранении блока в админ-панели. Подробнее о кэшировании блоков см. <a href="./../blocks/#кэширование-блоков">Блоки → Кэширование</a>.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../getting-started/interface.html">Обзор интерфейса</a> — структура админ-панели</li></ul>',11)])])}const u=e(l,[["render",o]]);export{_ as __pageData,u as default};
